{"results": [{"id": "FAM:SF-CHT-025", "label": "Study family SF-CHT-025: Play-type labeling audit: OTHER/DRIVE foul leakage", "score": 0.403, "reached_via": ["request matches the question or hypothesis of FAM:SF-CHT-025 (0.20)", "request matches RQC:RQC-087 (0.19); FAM:SF-CHT-025 auto_addresses_question RQC:RQC-087"], "attributes": {"observed_research_question": "Play-type labeling audit: OTHER/DRIVE foul leakage", "auto_outcome_status": "artifact", "observed_hypothesis": "Play-type PPP differences are real efficiency, not labeling/foul artifacts.", "observed_result": "OTHER: 36% end in fouls, PPP inflated (FOUL_BUCKET). DRIVE: 12pp below foul benchmark (FOUL_LEAK). PNR shows 22% foul rate. Only 335 of 50,668 possessions (0.7%) map to a real play type via initiation_type.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "OTHER PPP inflated by 36% foul endings; DRIVE 12pp below foul benchmark; initiation_type maps 0.7%.", "observed_sample_and_power": "50,668 possessions in the initiation_type check", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Per-PT diagnostic of foul-ending share vs PPP; initiation_type mapping.", "observed_verdict": "artifact_found"}, "relationships": []}, {"id": "FAM:SF07", "label": "Study family SF07: Sequential pair premium and defensive aftershock (8/8 PTs)", "score": 0.395, "reached_via": ["FAM:SF-APPA-050 auto_related_family (record_link_extends) FAM:SF07", "FAM:SF40 auto_related_family (record_link_related_to) FAM:SF07"], "attributes": {"observed_research_question": "Sequential pair premium and defensive aftershock (8/8 PTs)", "auto_outcome_status": "supported", "observed_hypothesis": "After the opponent runs play type X, the next offensive play type Y scores above Y's unconditional H2 baseline, and every PT has a defensive aftershock.", "observed_result": ["[APPA-049] A2 aftershock 8/8 PTs replicate all-games and playoffs (CUT +0.119 n=21,398 / PO +0.131 n=1,145 through TRANSITION +0.135 n=26,262 / +0.126 n=1,529). Top pair premiums: PUTBACK->TRANSITION +0.084 n=565; CUT->P [cut; read_family for the full text]", "[APPS-037] All-games aftershock after success: CUT +0.119 (n=21398), DRIVE +0.123 (57621), PNR +0.127 (51194), POST_UP +0.128 (20619), PULL_UP +0.132 (26060), PUTBACK +0.130 (5888), SPOT_UP +0.128 (43857), TRANSITION +0. [cut; read_family for the full text]"], "auto_failure_mechanism": "D_positive (no failure: positive result)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}]}, {"id": "FAM:SF-APPS-058", "label": "Study family SF-APPS-058: Observed on-ball defensive scheme labels (ORL-DET G1)", "score": 0.34, "reached_via": ["request matches RQC:RQC-079 (0.26); FAM:SF-APPS-058 auto_addresses_question RQC:RQC-079", "request matches VAR:PPP_points_per_possession (0.50); FAM:SF-APPS-058 auto_measures VAR:PPP_points_per_possession"], "attributes": {"observed_research_question": "Observed on-ball defensive scheme labels (ORL-DET G1)", "auto_outcome_status": "untestable", "observed_hypothesis": "NBA matchup/PBP fields can label on-ball coverage (DROP/ICE/SWITCH) at usable rates.", "observed_result": "DET: 67 on-ball HC poss, 10 labeled (14.9%) ? DROP n=5 PPP=1.20, ICE_CANDIDATE n=5 PPP=0.80, OTHER n=57 PPP=1.42. ORL: 60 poss, 2 labeled (3.3%). switches_on unpopulated.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Confident label rates 14.9% and 3.3%; NBA matchups feed did not populate switches_on.", "observed_sample_and_power": "n=67/60 possessions, 10/2 labeled", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "failed_gate"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPA-050", "label": "Study family SF-APPA-050: Superstar sequential suppression: opponent play before the star", "score": 0.323, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPA-050 (0.20)", "request matches VAR:PPP_points_per_possession (0.50); FAM:SF-APPA-050 auto_measures VAR:PPP_points_per_possession"], "attributes": {"observed_research_question": "Superstar sequential suppression: opponent play before the star", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "A specific opponent play type on the preceding possession suppresses each star's next-possession PPP relative to that star's baseline.", "observed_result": "PUTBACK is top suppressor for 6+ stars (e.g. D. Mitchell 1.178 to 0.884, d=-0.294, n_after=95; B. Beal d=-0.345 n=32; C. Holmgren d=-0.222 n=52). Other tops: TRANSITION (A. Davis -0.058), POST_UP (N. Jokic -0.075), PULL_ [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No multiplicity correction; n_after is 32-95 for several PUTBACK cells vs thousands of baseline possessions.", "observed_sample_and_power": "30 stars; min n_after=30", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:DRIFT_NONSTATIONARITY"}]}], "n_results": 4}

